#include "ShowControl.h"
#include "SongTransport.h"
namespace midnightShow {
void Coordinator::startGroup(const std::shared_ptr<Run>& r,double){
 if(r->cue->song.isNotEmpty()||r->cue->media.isObject()){require(r->cue->mode==GroupMode::Timeline,"A primary song uses Timeline Group mode");r->song=songFactory(*r->cue,++r->epoch);r->clockRoot=r->id;r->clockValid=false;r->songPosition=0;r->startedAt=0;r->detail="Primary song loading; schedule awaits its actual clock";return;}
 std::vector<std::shared_ptr<const CueSpec>> eligible;for(auto c:r->cue->children)if(c->eligible)eligible.push_back(c);require(!eligible.empty(),"Group has no eligible child");
 if(r->cue->mode==GroupMode::Timeline){std::stable_sort(eligible.begin(),eligible.end(),[](auto a,auto b){return a->pre<b->pre;});for(auto c:eligible){auto id=start(c,r->id,r->clockRoot,true,true);runs[id]->due=r->startedAt+c->pre;r->dispatched.insert(c->id);}r->scheduleClosed=true;}
 else if(r->cue->mode==GroupMode::Random){std::vector<std::shared_ptr<const CueSpec>> available;for(auto c:eligible){bool busy=false;for(auto p:runs)busy|=p.second->cue->id==c->id&&p.second->admitted&&p.second->outcome==Outcome::Pending;if(!busy)available.push_back(c);}require(!available.empty(),"Random: no eligible non-running children");auto& history=randomHistory[r->cue->id];bool unseen=false;for(auto c:available)unseen|=!history.count(c->id);if(!unseen)history.clear();available.erase(std::remove_if(available.begin(),available.end(),[&](auto c){return history.count(c->id)!=0;}),available.end());auto chosen=available[std::uniform_int_distribution<size_t>(0,available.size()-1)(random)];history.insert(chosen->id);note("Random selected "+String(chosen->id));start(chosen,r->id,r->clockRoot,false,true);r->scheduleClosed=true;}
 else {for(auto c:eligible)r->order.push_back(c->id);start(eligible.front(),r->id,r->clockRoot,false,r->cue->mode==GroupMode::Playlist);r->nextChild=1;r->scheduleClosed=r->cue->mode==GroupMode::StartFirst;}
}
void Coordinator::next(const Id& id){auto r=runs.at(id);require(r->cue->type==CueType::Group,"Select a Group run");require(r->admitted,"Group ended");if(r->nextChild>=r->order.size()){r->scheduleClosed=true;return;}auto nextId=r->order[r->nextChild++];for(auto c:r->cue->children)if(c->id==nextId){start(c,r->id,r->clockRoot,false,r->cue->mode==GroupMode::Playlist);break;}if(r->nextChild>=r->order.size()&&r->cue->mode==GroupMode::Enter)r->scheduleClosed=true;}
void Coordinator::songTick(const std::shared_ptr<Run>& r,double now){auto state=r->song->poll();r->clockValid=state.valid;if(!state.valid){r->detail=state.problem.isNotEmpty()?state.problem:"Primary song clock unavailable";return;}
 if(r->seekStart>=0){r->song->seek(r->seekStart);r->seekFloor=r->song->poll().position;r->seekStart=-1;r->song->pause(false);state=r->song->poll();r->paused=false;}
 if(state.epoch!=r->epoch){r->epoch=state.epoch;r->scheduledIteration=0;r->dispatched.clear();for(auto id:r->children){auto child=runs[id];if(!child->started){child->admitted=false;child->continuationSent=true;finish(child,Outcome::Cancelled,"Skipped by explicit song seek");}}note(r->cue->name+": new explicit transport epoch; earlier placements skipped");}
 r->songPosition=state.elapsed;r->iteration=state.iteration;r->detail=(r->paused?"Song paused at ":"Song ")+String(state.position,3)+" s | epoch "+String(int64(state.epoch))+" iteration "+String(int64(state.iteration))+"; edits affect later starts";
 if(r->paused||!state.playing&&!state.finished)return;
 std::vector<std::shared_ptr<const CueSpec>> ordered;for(auto child:r->cue->children)if(child->eligible)ordered.push_back(child);std::stable_sort(ordered.begin(),ordered.end(),[](auto a,auto b){return a->pre<b->pre;});
 const double span=state.loopEnd-state.loopStart;for(uint64_t iteration=r->scheduledIteration;iteration<=state.iteration;++iteration){for(auto child:ordered){const Id occurrence=std::to_string(r->epoch)+"/"+std::to_string(iteration)+"/"+child->id;if(r->dispatched.count(occurrence))continue;
  if(child->pre<state.loopStart||child->pre>state.loopEnd||(iteration==0&&child->pre<r->seekFloor)){r->dispatched.insert(occurrence);note("Skipped earlier/outside-region occurrence "+child->name+" at "+String(child->pre,3));continue;}
  const double due=iteration*span+child->pre-state.loopStart;if(due>state.elapsed)continue;r->dispatched.insert(occurrence);
  bool ignored=false;std::vector<Id> replaced;for(auto id:r->children){auto old=runs[id];if(old->cue->id!=child->id||!old->admitted)continue;if(child->ignore&&old->outcome==Outcome::Pending){ignored=true;break;}replaced.push_back(id);}if(ignored){note(child->name+": repeated occurrence ignored by explicit cue choice");continue;}
  for(auto id:replaced){auto old=runs[id];if(child->type==CueType::Motion||child->type==CueType::Step){old->admitted=false;old->continuationSent=true;}else end(id);}
  auto id=start(child,r->id,r->id,true,true);auto run=runs[id];run->due=due;run->epoch=state.epoch;run->iteration=iteration;launch(run,now);
 }if(iteration<state.iteration)r->scheduledIteration=iteration+1;}
 if(state.finished)r->scheduleClosed=true;
}
void Coordinator::groupTick(const std::shared_ptr<Run>& r,double now){if(!r->admitted)return;if(r->song)songTick(r,now);
 if(r->cue->mode==GroupMode::Playlist&&!r->scheduleClosed&&!r->children.empty()&&schedulingAllowed(*r)){auto child=runs[r->children.back()];if(child->outcome==Outcome::Succeeded&&isFinite(*child->cue))next(r->id);else if(child->outcome==Outcome::Failed)r->detail="Playlist branch failed; Retry failed members or explicit Next";else if(!isFinite(*child->cue))r->detail="Persistent child: explicit Next advances without ending it";}
 bool all=true,failed=false;for(auto id:r->children){auto child=runs[id];if(!child->started&&!child->admitted)continue;all&=child->started;all&=child->cue->continuation==0||child->continuationSent;failed|=child->outcome==Outcome::Failed;if(isFinite(*child->cue))all&=child->outcome==Outcome::Succeeded;}
 if(r->scheduleClosed&&failed)finish(r,Outcome::Failed,"A required descendant failed; retained work remains independently endable");if(r->scheduleClosed&&all)finish(r,Outcome::Succeeded,"Group schedule closed; finite descendants succeeded; retained descendants remain owned");
}
void Coordinator::pause(const Id& id,bool pause){auto r=runs.at(id);require(bool(r->song),"Pause/Resume applies to the primary song; native motors continue independently");auto state=r->song->poll();if(!pause&&state.finished){note("Song EOF: Resume is a no-op; use explicit Restart");return;}r->paused=pause;r->song->pause(pause);note(pause?"Song and future scene launches paused; already-started native work continues":"Song resumed at the same position; no replay or motor gate");}
void Coordinator::seek(const Id& id,double position){auto r=runs.at(id);require(bool(r->song),"Select an active music scene");finite(position);require(r->admitted&&r->outcome==Outcome::Pending,"Finished scene: use Start from cursor for a new run");r->song->seek(position);r->paused=true;r->seekFloor=r->song->poll().position;r->scheduleClosed=false;note("Explicit song seek is inert; earlier occurrences will be skipped on Resume");}
Id Coordinator::startFromHere(const Id& cueId,double position){auto cue=find(cueId);require(cue&&cue->type==CueType::Group,"Select a music Group");std::vector<Id> old;for(auto p:runs)if(p.second->cue->id==cueId&&p.second->admitted)old.push_back(p.first);for(auto id:old)end(id);auto id=start(cue->snapshot(),{},{},true);runs[id]->seekStart=position;runs[id]->seekFloor=position;tick();return id;}
void Coordinator::tap(const Id& id){auto r=runs.at(id);require(bool(r->song),"Select an active music scene");auto state=r->song->poll();require(state.valid,"Primary song clock unavailable; tap cannot fabricate time");auto cue=find(r->cue->id);require(cue&&cue->markers,"Scene definition was deleted; active run remains endable");remember();cue->markers->addCueAt(float(state.position));if(Engine::mainEngine)Engine::mainEngine->changed();++revision;note("Tap marker at actual song "+String(state.position,4)+" s");}
}
